from fastapi import FastAPI
from pydantic import BaseModel, ConfigDict
from fastapi.testclient import TestClient

class MyClass:
    def __init__(self, name: str):
        self.name = name
    def __repr__(self):
        return f"MyClass(name={self.name})"

class MyModel(BaseModel):
    model_config = ConfigDict(arbitrary_types_allowed=True)
    item: MyClass

app = FastAPI()

@app.post("/test")
async def test_endpoint(item: MyModel):
    return {"item": str(item.item)}

client = TestClient(app)

def test_arbitrary_type():
    # This should work if arbitrary_types_allowed=True is handled correctly
    # However, we need to send data that Pydantic can use to instantiate MyClass.
    # Pydantic v2 with arbitrary_types_allowed=True usually just does a check
    # or tries to instantiate if it can.
    # For a simple class, it might just assign the value if it matches.

    # Let's see what happens.
    try:
        response = client.post("/test", json={"item": "some_value"})
        print(f"Response: {response.json()}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    test_arbitrary_type()
